#[test]
fn new_and_convert_to_match_named_methods() {
    let v = 1234.5;
    assert_eq!(
        ThermalResistance::new(v, ThermalResistanceUnit::KelvinPerWatt),
        ThermalResistance::from_kelvins_per_watt(v)
    );
    assert_eq!(
        ThermalResistance::from_base(v).convert_to(ThermalResistanceUnit::KelvinPerWatt),
        ThermalResistance::from_base(v).as_kelvins_per_watt()
    );
    assert_eq!(
        ThermalResistance::new(v, ThermalResistanceUnit::DegreeCelsiusPerWatt),
        ThermalResistance::from_degrees_celsius_per_watt(v)
    );
    assert_eq!(
        ThermalResistance::from_base(v).convert_to(ThermalResistanceUnit::DegreeCelsiusPerWatt),
        ThermalResistance::from_base(v).as_degrees_celsius_per_watt()
    );
}

#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = ThermalResistance::from_base(v);
        let auto = q.auto_unit();
        assert_close(
            ThermalResistance::new(auto.value, auto.unit).as_base(),
            v,
            F64_TOL,
        );
        for &unit in ThermalResistanceUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        ThermalResistance::from_base(0.0).auto_unit().unit,
        ThermalResistanceUnit::KelvinPerWatt
    );
}

#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "K/W".parse::<ThermalResistanceUnit>(),
        Ok(ThermalResistanceUnit::KelvinPerWatt)
    );
    assert_eq!(
        format!("2.5 {}", "K/W").parse::<ThermalResistance>(),
        Ok(ThermalResistance::new(
            2.5,
            ThermalResistanceUnit::KelvinPerWatt
        ))
    );
    assert_eq!(
        "°C/W".parse::<ThermalResistanceUnit>(),
        Ok(ThermalResistanceUnit::DegreeCelsiusPerWatt)
    );
    assert_eq!(
        format!("2.5 {}", "°C/W").parse::<ThermalResistance>(),
        Ok(ThermalResistance::new(
            2.5,
            ThermalResistanceUnit::DegreeCelsiusPerWatt
        ))
    );
    assert_eq!(
        "1 not-a-unit".parse::<ThermalResistance>(),
        Err(ParseError::UnknownUnit)
    );
}

#[test]
fn arithmetic_f64() {
    let a = ThermalResistance::from_base(6.0);
    let b = ThermalResistance::from_base(2.0);
    assert_eq!((a + b).as_base(), 8.0);
    assert_eq!((a - b).as_base(), 4.0);
    assert_eq!((-a).as_base(), -6.0);
    assert_eq!((a * 2.0).as_base(), 12.0);
    assert_eq!((2.0 * a).as_base(), 12.0);
    assert_eq!((a / 2.0).as_base(), 3.0);
    assert_eq!(a / b, 3.0);
    let mut c = a;
    c += b;
    c -= b;
    c *= 2.0;
    c /= 4.0;
    assert_eq!(c.as_base(), 3.0);
}

#[test]
fn arithmetic_integer() {
    let a = ThermalResistance::<i64>::from_base(7);
    let b = ThermalResistance::<i64>::from_base(2);
    assert_eq!(a + b, ThermalResistance::from_base(9));
    assert_eq!(a % b, ThermalResistance::from_base(1));
    assert_eq!(a / b, 3);
    assert!(a > b);
    assert_eq!(
        [a, b].iter().sum::<ThermalResistance<i64>>(),
        ThermalResistance::from_base(9)
    );
}
